import sys

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass

_HEX_DIGIT = {c: int(c, 16) for c in "0123456789abcdefABCDEF"}


def parse_json(text: str) -> object:
    n = len(text)
    ws = " \t\n\r"
    digits = "0123456789"
    hex_digit = _HEX_DIGIT

    def read_string(pos, text=text, n=n, hex_digit=hex_digit):
        pos += 1
        start = pos
        parts = []
        get_hex = hex_digit.get

        while pos < n:
            ch = text[pos]

            if ch == '"':
                if start < pos:
                    parts.append(text[start:pos])
                return ''.join(parts), pos + 1

            if ch == '\\':
                if start < pos:
                    parts.append(text[start:pos])

                pos += 1
                if pos >= n:
                    raise ValueError

                esc = text[pos]

                if esc == 'u':
                    pos += 1
                    code = 0

                    for _ in range(4):
                        if pos >= n:
                            raise ValueError
                        v = get_hex(text[pos])
                        if v is None:
                            raise ValueError
                        code = (code << 4) + v
                        pos += 1

                    if 0xD800 <= code <= 0xDBFF:
                        if pos + 5 >= n or text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError

                        pos += 2
                        low = 0

                        for _ in range(4):
                            if pos >= n:
                                raise ValueError
                            v = get_hex(text[pos])
                            if v is None:
                                raise ValueError
                            low = (low << 4) + v
                            pos += 1

                        if not (0xDC00 <= low <= 0xDFFF):
                            raise ValueError

                        parts.append(chr(0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)))
                        start = pos
                        continue

                    if 0xDC00 <= code <= 0xDFFF:
                        raise ValueError

                    parts.append(chr(code))
                    start = pos
                    continue

                elif esc == '"':
                    parts.append('"')
                    pos += 1
                elif esc == '\\':
                    parts.append('\\')
                    pos += 1
                elif esc == '/':
                    parts.append('/')
                    pos += 1
                elif esc == 'b':
                    parts.append('\b')
                    pos += 1
                elif esc == 'f':
                    parts.append('\f')
                    pos += 1
                elif esc == 'n':
                    parts.append('\n')
                    pos += 1
                elif esc == 'r':
                    parts.append('\r')
                    pos += 1
                elif esc == 't':
                    parts.append('\t')
                    pos += 1
                else:
                    raise ValueError

                start = pos
                continue

            oc = ord(ch)

            if oc < 0x20:
                raise ValueError

            if 0xD800 <= oc <= 0xDBFF:
                if start < pos:
                    parts.append(text[start:pos])

                if pos + 6 >= n or text[pos + 1] != '\\' or text[pos + 2] != 'u':
                    raise ValueError

                pos += 3
                low = 0

                for _ in range(4):
                    if pos >= n:
                        raise ValueError
                    v = get_hex(text[pos])
                    if v is None:
                        raise ValueError
                    low = (low << 4) + v
                    pos += 1

                if not (0xDC00 <= low <= 0xDFFF):
                    raise ValueError

                parts.append(chr(0x10000 + ((oc - 0xD800) << 10) + (low - 0xDC00)))
                start = pos
                continue

            if 0xDC00 <= oc <= 0xDFFF:
                raise ValueError

            pos += 1

        raise ValueError

    def read_number(pos, text=text, n=n, digits=digits):
        start = pos
        is_float = False

        if pos < n and text[pos] == '-':
            pos += 1

        if pos >= n:
            raise ValueError

        c = text[pos]

        if c == '0':
            pos += 1
        elif '1' <= c <= '9':
            pos += 1
            while pos < n and text[pos] in digits:
                pos += 1
        else:
            raise ValueError

        if pos < n and text[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or text[pos] not in digits:
                raise ValueError
            while pos < n and text[pos] in digits:
                pos += 1

        if pos < n and (text[pos] == 'e' or text[pos] == 'E'):
            is_float = True
            pos += 1
            if pos < n and (text[pos] == '+' or text[pos] == '-'):
                pos += 1
            if pos >= n or text[pos] not in digits:
                raise ValueError
            while pos < n and text[pos] in digits:
                pos += 1

        s = text[start:pos]
        if is_float:
            return float(s), pos
        return int(s), pos

    value = None
    i = 0
    stack = []
    state = 0

    while True:
        if state == 0:
            while i < n and text[i] in ws:
                i += 1
            if i >= n:
                raise ValueError

            c = text[i]

            if c == '{':
                stack.append([1, {}, set(), None])
                i += 1
                state = 3
            elif c == '[':
                stack.append([0, []])
                i += 1
                state = 2
            elif c == '"':
                value, i = read_string(i)
                state = 1
            elif c == 't':
                if not text.startswith('true', i):
                    raise ValueError
                i += 4
                value = True
                state = 1
            elif c == 'f':
                if not text.startswith('false', i):
                    raise ValueError
                i += 5
                value = False
                state = 1
            elif c == 'n':
                if not text.startswith('null', i):
                    raise ValueError
                i += 4
                value = None
                state = 1
            elif c == '-' or '0' <= c <= '9':
                value, i = read_number(i)
                state = 1
            else:
                raise ValueError

        elif state == 1:
            if not stack:
                while i < n and text[i] in ws:
                    i += 1
                if i != n:
                    raise ValueError
                return value

            frame = stack[-1]
            while i < n and text[i] in ws:
                i += 1
            if i >= n:
                raise ValueError

            c = text[i]

            if frame[0] == 0:
                frame[1].append(value)

                if c == ',':
                    i += 1
                    state = 0
                elif c == ']':
                    i += 1
                    value = frame[1]
                    stack.pop()
                    state = 1
                else:
                    raise ValueError
            else:
                frame[1][frame[3]] = value

                if c == ',':
                    i += 1
                    state = 4
                elif c == '}':
                    i += 1
                    value = frame[1]
                    stack.pop()
                    state = 1
                else:
                    raise ValueError

        elif state == 2:
            while i < n and text[i] in ws:
                i += 1
            if i >= n:
                raise ValueError

            if text[i] == ']':
                i += 1
                value = stack[-1][1]
                stack.pop()
                state = 1
            else:
                state = 0

        elif state == 3:
            while i < n and text[i] in ws:
                i += 1
            if i >= n:
                raise ValueError

            if text[i] == '}':
                i += 1
                value = stack[-1][1]
                stack.pop()
                state = 1
            else:
                state = 4

        elif state == 4:
            while i < n and text[i] in ws:
                i += 1
            if i >= n or text[i] != '"':
                raise ValueError

            key, i = read_string(i)
            frame = stack[-1]
            keys = frame[2]

            if key in keys:
                raise ValueError
            keys.add(key)
            frame[3] = key

            while i < n and text[i] in ws:
                i += 1
            if i >= n or text[i] != ':':
                raise ValueError
            i += 1
            state = 0
